    CatalogueController_images: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                id: string;
            };
            cookie?: never;
        };
        /** @description REQUEST_UPLOAD signs the three derivative PUTs; COMMIT registers what landed. The keys are server-minted at signing, so a commit can only name keys this API chose. */
        requestBody: {
            content: {
                "application/json": {
                    /** @enum {string} */
                    action: "REQUEST_UPLOAD";
                    position: number;
                } | {
                    /** @enum {string} */
                    action: "COMMIT";
                    card_key: string;
                    full_key: string;
                    position: number;
                    thumb_key: string;
                };
            };
        };
        responses: {
            /** @description REQUEST_UPLOAD: three presigned PUTs, each with the key the commit must name. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        uploads: {
                            card: {
                                key: string;
                                /** Format: uri */
                                url: string;
                            };
                            full: {
                                key: string;
                                /** Format: uri */
                                url: string;
                            };
                            thumb: {
                                key: string;
                                /** Format: uri */
                                url: string;
                            };
                        };
                    };
                };
            };
            /** @description COMMIT: the image row is registered. */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description slots.reason is IMAGE_CAP_REACHED (checked BEFORE signing), OBJECT_NOT_UPLOADED, or POSITION_TAKEN. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
